    @Test
    fun matchesScipy() {
        for ((name, f) in fixtures) {
            val z = linkage(f.d, f.method)
            assertContentEquals(f.left, z.left, "$name: left")
            assertContentEquals(f.right, z.right, "$name: right")
            for (i in f.height.indices) assertEquals(f.height[i], z.height[i], 1e-12, "$name: height $i")
            assertContentEquals(f.leaves, z.leaves(), "$name: leaves")
            f.cuts.forEachIndexed { i, expected -> assertContentEquals(expected, z.cut(i + 1), "$name: k=${i + 1}") }
        }
    }

    @Test
    fun kendallTauBMatchesScipy() {
        // scipy.stats.kendalltau([0, 1, 1, 2, 3, 3, 0], [1, 1, 0, 2, 2, 3, 0]).statistic
        assertEquals(0.7222222222222224, kendallTauB(intArrayOf(0, 1, 1, 2, 3, 3, 0), intArrayOf(1, 1, 0, 2, 2, 3, 0)), 1e-12)
    }
